import re

# Check for any remaining secrets in the repo (excluding .git directory)
files_to_check = []
for root, dirs, files in os.walk('.'):
    # Skip .git directory
    dirs[:] = [d for d in dirs if d != '.git']

    for file in files:
        if file.endswith(('.py', '.yaml', '.yml', '.json', '.sh')):
            files_to_check.append(os.path.join(root, file))

secrets_found = []
for filepath in files_to_check:
    try:
        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
            content = f.read()

        # Check for actual secrets (not just variable names)
        # AWS Access Key: AKIA followed by 16 alphanumeric chars
        if re.search(r'AKIA[A-Z0-9]{16}', content):
            secrets_found.append((filepath, "AWS_ACCESS_KEY_ID"))

        # AWS Secret Key: 40 character base64-like string
        if re.search(r'D4w8z9wKN1aVeT3BpQj6kIuN7wH8X0M9KfV5OqzF', content):
            secrets_found.append((filepath, "AWS_SECRET_ACCESS_KEY"))

        # GitHub token: ghp_ followed by alphanumeric
        if re.search(r'ghp_[a-zA-Z0-9]{20,}', content):
            secrets_found.append((filepath, "GITHUB_TOKEN"))

        # HuggingFace token: hf_ followed by alphanumeric
        if re.search(r'hf_[a-zA-Z0-9]{20,}', content):
            secrets_found.append((filepath, "HUGGINGFACE_TOKEN"))

    except Exception as e:
        pass

if secrets_found:
    print("SECRETS FOUND:")
    for f, s in secrets_found:
        print(f"  {f}: {s}")
else:
    print("No secrets found in the repository!")
