# Check for any remaining secrets
secrets_found = []
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d != '.git' and d != '__pycache__']
    for file in files:
        if file.endswith(('.py', '.yaml', '.yml', '.json', '.sh', '.txt')):
            filepath = os.path.join(root, file)
            try:
                with open(filepath, 'rb') as f:
                    content = f.read()

                # Check for actual secrets (not variable names)
                if re.search(rb'AKIA[A-Z0-9]{16}', content):
                    secrets_found.append((filepath, "AWS_ACCESS_KEY_ID"))
                if re.search(rb'D4w8z9wKN1aVeT3BpQj6kIuN7wH8X0M9KfV5OqzF', content):
                    secrets_found.append((filepath, "AWS_SECRET_ACCESS_KEY"))
                if re.search(rb'ghp_[a-zA-Z0-9]{20,}', content):
                    secrets_found.append((filepath, "GITHUB_TOKEN"))
                if re.search(rb'hf_[a-zA-Z0-9]{20,}', content):
                    secrets_found.append((filepath, "HUGGINGFACE_TOKEN"))
            except:
                pass

