    if os.path.exists(filepath):
        with open(filepath, 'r') as f:
            content = f.read()
        if placeholder in content:
            print(f"✓ {name} placeholder found in {filepath}")
        else:
            print(f"✗ {name} placeholder NOT found in {filepath}")
            all_ok = False
    else:
        print(f"⚠ File {filepath} not found")

